<template>
  <main class="paper-shell"><div class="paper-container tool-container">
    <header class="paper-workspace-header"><div><div class="paper-page-eyebrow">Knowledge Base / Timeline</div><h1 class="paper-page-title">Publication timeline</h1><p class="paper-page-description">Filter the original publication timeline and inspect every paper in the selected interval.</p></div></header>
    <LiteratureKnowledgeNav />
    <section class="paper-panel range-panel"><div class="range-heading"><strong>Year range</strong><span>{{ yearFrom }}–{{ yearTo }}</span></div><div class="range-controls"><label>From year<input v-model.number="yearFrom" type="range" :min="minYear" :max="maxYear" @change="normalizeRange('from')" /><output>{{ yearFrom }}</output></label><label>To year<input v-model.number="yearTo" type="range" :min="minYear" :max="maxYear" @change="normalizeRange('to')" /><output>{{ yearTo }}</output></label><button class="paper-button primary" @click="applyRange">Apply range</button></div></section>
    <p v-if="error" class="notice">{{ error }}</p>
    <section class="paper-panel timeline-panel"><div class="section-heading"><strong>Research activity</strong><span>{{ filteredYears.length }} years · {{ papers.length }} papers</span></div><div ref="chart" class="timeline-chart"><div class="empty">{{ pending ? 'Loading timeline…' : 'No valid year data.' }}</div></div></section>
    <section class="paper-panel papers-panel"><div class="section-heading"><strong>Papers in this interval</strong><span>Sorted by year</span></div><table v-if="papers.length"><thead><tr><th>Title</th><th>Year</th><th>Journal</th><th>Citations</th></tr></thead><tbody><tr v-for="paper in papers" :key="paper.id" @click="router.push(`/literature/${paper.id}`)"><td>{{ paper.title }}</td><td>{{ paper.year || '—' }}</td><td>{{ paper.journal || '—' }}</td><td>{{ paper.citation_count || 0 }}</td></tr></tbody></table><div v-else class="empty">No papers in this interval.</div></section>
  </div></main>
</template>
<script setup>
import '~/assets/paper-platform.css'; import LiteratureKnowledgeNav from '~/components/LiteratureKnowledgeNav.vue'
const config=useRuntimeConfig(),router=useRouter(),route=useRoute(),chart=ref(null),allYears=ref([]),papers=ref([]),pending=ref(false),error=ref(''),yearFrom=ref(null),yearTo=ref(null)
useHead({title:'Literature Timeline - OpenIsle'})
const validYears=computed(()=>allYears.value.filter(item=>/^\d{4}$/.test(String(item.year))&&Number(item.paper_count)>0));const minYear=computed(()=>validYears.value.length?Math.min(...validYears.value.map(x=>+x.year)):2000);const maxYear=computed(()=>validYears.value.length?Math.max(...validYears.value.map(x=>+x.year)):new Date().getFullYear());const filteredYears=computed(()=>validYears.value.filter(x=>+x.year>=yearFrom.value&&+x.year<=yearTo.value))
const chartLabels={
  'timeline.chart.paper_count':'Papers',
  'timeline.chart.parse_done':'Parsed papers',
  'timeline.chart.data_points':'Data points',
  'timeline.chart.y_left_label':'Papers / parsed papers',
  'timeline.chart.y_right_label':'Data points'
}
const ensureCharts=async()=>{window.Utils={...(window.Utils||{}),truncate:(v,n)=>String(v||'').slice(0,n),escapeHtml:v=>String(v||'')};const previousTranslate=window.I18n?.t?.bind(window.I18n);window.I18n={...(window.I18n||{}),t:key=>chartLabels[key]||(previousTranslate?previousTranslate(key):key)};if(window.OpenIsleLiteratureCharts)return window.OpenIsleLiteratureCharts;await new Promise((ok,bad)=>{const s=document.createElement('script');s.src='/literature-engine/charts.js';s.onload=ok;s.onerror=bad;document.head.appendChild(s)});return window.OpenIsleLiteratureCharts}
const normalizeRange=source=>{if(yearFrom.value>yearTo.value){if(source==='from')yearTo.value=yearFrom.value;else yearFrom.value=yearTo.value}}
const applyRange=async()=>{normalizeRange('from');pending.value=true;error.value='';try{const params=new URLSearchParams({year_from:String(yearFrom.value),year_to:String(yearTo.value),limit:'100',sort:'year_desc'});const data=await $fetch(`${config.public.apiBaseUrl}/api/literature/explore/papers/list?${params}`);papers.value=data.papers||[];const charts=await ensureCharts();charts.timelineChart(chart.value,filteredYears.value);await router.replace({query:{year_from:yearFrom.value,year_to:yearTo.value}})}catch(cause){error.value=cause?.data?.message||cause?.message||'Unable to load timeline.'}finally{pending.value=false}}
onMounted(async()=>{try{const data=await $fetch(`${config.public.apiBaseUrl}/api/literature/explore/timeline`);allYears.value=data.years||[];yearFrom.value=Math.max(minYear.value,Number(route.query.year_from)||minYear.value);yearTo.value=Math.min(maxYear.value,Number(route.query.year_to)||maxYear.value);await applyRange()}catch(cause){error.value=cause?.message||'Unable to load timeline.'}})
</script>
<style scoped>
.tool-container{max-width:1180px}.range-panel{padding:15px;margin-bottom:16px}.range-heading{display:flex;justify-content:space-between;margin-bottom:12px}.range-heading span{color:var(--paper-teal);font-weight:800}.range-controls{display:grid;grid-template-columns:1fr 1fr auto;gap:16px;align-items:end}.range-controls label{display:grid;grid-template-columns:1fr auto;gap:5px;color:var(--paper-muted);font-size:11px;font-weight:750}.range-controls input{grid-column:1/-1;width:100%;accent-color:var(--paper-teal)}.range-controls output{color:var(--paper-ink)}.timeline-panel,.papers-panel{overflow:hidden;margin-bottom:16px}.section-heading{display:flex;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--paper-line)}.section-heading span{color:var(--paper-muted);font-size:11px}.timeline-chart{min-height:320px;padding:18px}.papers-panel table{width:100%;border-collapse:collapse}.papers-panel th,.papers-panel td{padding:11px 15px;border-bottom:1px solid var(--paper-line);text-align:left;font-size:12px}.papers-panel th{color:var(--paper-muted);font-size:10px;text-transform:uppercase}.papers-panel tbody tr{cursor:pointer}.papers-panel tbody tr:hover{background:#f5f9fa}.empty{display:grid;place-items:center;min-height:120px;color:var(--paper-muted)}.notice{padding:10px 14px;background:#fff4f2;color:#8b3028}@media(max-width:700px){.range-controls{grid-template-columns:1fr}}
</style>
